'use client';

import { useState } from 'react';

type Unit = 'celsius' | 'fahrenheit' | 'kelvin';

type Values = Record<Unit, string>;

const UNITS: Array<{ key: Unit; label: string; symbol: string }> = [
  { key: 'celsius', label: 'Celsius', symbol: '°C' },
  { key: 'fahrenheit', label: 'Fahrenheit', symbol: '°F' },
  { key: 'kelvin', label: 'Kelvin', symbol: 'K' },
];

const ABSOLUTE_ZERO: Record<Unit, number> = {
  celsius: -273.15,
  fahrenheit: -459.67,
  kelvin: 0,
};

const INITIAL_VALUES: Values = {
  celsius: '0',
  fahrenheit: '32',
  kelvin: '273.15',
};

function parseTemperature(value: string): number | null {
  if (value.trim() === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatTemperature(value: number): string {
  if (!Number.isFinite(value)) return '';
  const rounded = Math.round(value * 1_000_000) / 1_000_000;
  return String(Object.is(rounded, -0) ? 0 : rounded);
}

function convertFrom(unit: Unit, value: number): Record<Unit, number> {
  if (unit === 'celsius') {
    return {
      celsius: value,
      fahrenheit: value * (9 / 5) + 32,
      kelvin: value + 273.15,
    };
  }

  if (unit === 'fahrenheit') {
    return {
      celsius: (value - 32) * (5 / 9),
      fahrenheit: value,
      kelvin: (value - 32) * (5 / 9) + 273.15,
    };
  }

  return {
    celsius: value - 273.15,
    fahrenheit: (value - 273.15) * (9 / 5) + 32,
    kelvin: value,
  };
}

export default function TemperatureConverterPage() {
  const [values, setValues] = useState<Values>(INITIAL_VALUES);

  function handleChange(unit: Unit, rawValue: string) {
    setValues((previous) => {
      const next: Values = { ...previous, [unit]: rawValue };

      if (rawValue.trim() === '') {
        return { celsius: '', fahrenheit: '', kelvin: '' };
      }

      const numericValue = Number(rawValue);
      if (!Number.isFinite(numericValue)) {
        return next;
      }

      const converted = convertFrom(unit, numericValue);

      for (const { key } of UNITS) {
        if (key !== unit) {
          next[key] = formatTemperature(converted[key]);
        }
      }

      return next;
    });
  }

  const isBelowAbsoluteZero = UNITS.some(({ key }) => {
    const numericValue = parseTemperature(values[key]);
    return numericValue !== null && numericValue < ABSOLUTE_ZERO[key];
  });

  return (
    <main style={styles.main}>
      <section style={styles.card}>
       ...
      </section>
    </main>
  );
}
```

