```
'use client';

import { useState, type CSSProperties } from 'react';

type Unit = 'celsius' | 'fahrenheit' | 'kelvin';

type Values = Record<Unit, string>;

const UNITS: Array<{ key: Unit; label: string; symbol: string }> = [
  { key: 'celsius', label: 'Celsius', symbol: '°C' },
  { key: 'fahrenheit', label: 'Fahrenheit', symbol: '°F' },
  { key: 'kelvin', label: 'Kelvin', symbol: 'K' },
];

const ABSOLUTE_ZERO: Record<Unit, number> = { ... };

const INITIAL_VALUES: Values = { ... };

function parseTemperature(value: string): number | null { ... }

function formatTemperature(value: number): string { ... }

function convertFrom(unit: Unit, value: number): Record<Unit, number> { ... }

export default function TemperatureConverterPage() {
  const [values, setValues] = useState<Values>(INITIAL_VALUES);

  function handleChange(unit: Unit, rawValue: string) {
    setValues((previous) => {
      if (rawValue.trim() === '') {
        return { celsius: '', fahrenheit: '', kelvin: '' };
      }

      const numericValue = Number(rawValue);

      if (!Number.isFinite(numericValue)) {
        const onlyActiveValue: Values = { celsius: '', fahrenheit: '', kelvin: '' };
        onlyActiveValue[unit] = rawValue;
        return onlyActiveValue;
      }

      const converted = convertFrom(unit, numericValue);
      const next: Values = { ...previous, [unit]: rawValue };

      for (const { key } of UNITS) {
        if (key !== unit) {
          next[key] = formatTemperature(converted[key]);
        }
      }

      return next;
    });
  }

  const isBelowAbsoluteZero = UNITS.some(({ key }) => {
    const numericValue = parseTemperature(values[key]);
    return numericValue !== null && numericValue < ABSOLUTE_ZERO[key];
  });

  return (
    <main style={styles.main}>
      <section style={styles.card} aria-labelledby="converter-title">
        <h1 id="converter-title" style={styles.h1}>Temperature Converter</h1>
        <p style={styles.intro}>Type a temperature in any field. The other two scales update automatically.</p>
        <div style={styles.grid}>
          {UNITS.map(({ key, label, symbol }) => (
            <div key={key} style={styles.field}>
              <label htmlFor={`temperature-${key}`} style={styles.label}>{label}</label>
              <div style={styles.inputRow}>
                <input
                  id={`temperature-${key}`}
                  type="text"
                  inputMode="decimal"
                  autoComplete="off"
                  value={values[key]}
                  onChange={(event) => handleChange(key, event.target.value)}
                  style={styles.input}
                  aria-invalid={isBelowAbsoluteZero || undefined}
                />
                <span style={styles.suffix}>{symbol}</span>
              </div>
            </div>
          ))}
        </div>
        {isBelowAbsoluteZero && (
          <p role="alert" style={styles.warning}>This temperature is below absolute zero. Enter a physically valid value.</p>
        )}
        <p style={styles.hint}>Absolute zero is 0 K, -273.15 °C, or -459.67 °F.</p>
      </section>
    </main>
  );
}
```

