// app/page.tsx
'use client';

import { useState, type CSSProperties } from 'react';

type Unit = 'celsius' | 'fahrenheit' | 'kelvin';

type Values = Record<Unit, string>;

const UNITS: Array<{ key: Unit; label: string; symbol: string }> = [
  { key: 'celsius', label: 'Celsius', symbol: '°C' },
  { key: 'fahrenheit', label: 'Fahrenheit', symbol: '°F' },
  { key: 'kelvin', label: 'Kelvin', symbol: 'K' },
];

const ABSOLUTE_ZERO: Record<Unit, number> = {
  celsius: -273.15,
  fahrenheit: -459.67,
  kelvin: 0,
};

const INITIAL_VALUES: Values = {
  celsius: '0',
  fahrenheit: '32',
  kelvin: '273.15',
};

function parseTemperature(value: string): number | null {
  if (value.trim() === '') return null;

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatTemperature(value: number): string {
  if (!Number.isFinite(value)) return '';

  const rounded = Math.round(value * 1_000_000) / 1_000_000;
  return String(Object.is(rounded, -0) ? 0 : rounded);
}

function convertFrom(unit: Unit, value: number): Record<Unit, number> {
  if (unit === 'celsius') {
    return {
      celsius: value,
      fahrenheit: value * (9 / 5) + 32,
      kelvin: value + 273.15,
    };
  }

  if (unit === 'fahrenheit') {
    return {
      celsius: (value - 32) * (5 / 9),
      fahrenheit: value,
      kelvin: (value - 32) * (5 / 9) + 273.15,
    };
  }

  return {
    celsius: value - 273.15,
    fahrenheit: (value - 273.15) * (9 / 5) + 32,
    kelvin: value,
  };
}

const styles: Record<string, CSSProperties> = {
  main: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '2rem',
    background: '#f4f7fb',
    color: '#0f172a',
    fontFamily:
      'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
  },
  card: {
    width: '100%',
    maxWidth: '760px',
    background: '#ffffff',
    borderRadius: '1rem',
    padding: '2rem',
    boxShadow: '0 20px 60px rgba(15, 23, 42, 0.12)',
  },
  h1: {
    margin: '0 0 0.5rem',
    fontSize: 'clamp(1.75rem, 4vw, 2.5rem)',
    lineHeight: 1.1,
  },
  intro: {
    margin: '0 0 1.5rem',
    color: '#475569',
    lineHeight: 1.6,
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
    gap: '1rem',
  },
  field: {
    display: 'flex',
    flexDirection: 'column',
    gap: '0.5rem',
  },
  label: {
    fontWeight: 600,
    color: '#334155',
  },
  inputRow: {
    display: 'flex',
    alignItems: 'center',
    border: '1px solid #cbd5e1',
    borderRadius: '0.75rem',
    overflow: 'hidden',
    background: '#f8fafc',
  },
  input: {
    flex: 1,
    minWidth: 0,
    border: 'none',
    outline: 'none',
    background: 'transparent',
    padding: '0.85rem 1rem',
    fontSize: '1.15rem',
    color: '#0f172a',
  },
  suffix: {
    padding: '0 0.9rem',
    color: '#64748b',
    fontWeight: 600,
    borderLeft: '1px solid #e2e8f0',
    alignSelf: 'stretch',
    display: 'flex',
    alignItems: 'center',
  },
  warning: {
    marginTop: '1.25rem',
    padding: '0.9rem 1rem',
    borderRadius: '0.75rem',
    background: '#fef2f2',
    border: '1px solid #fecaca',
    color: '#991b1b',
    fontWeight: 600,
  },
  hint: {
    marginTop: '1.25rem',
    color: '#64748b',
    fontSize: '0.9rem',
  },
};

export default function TemperatureConverterPage() {
  const [values, setValues] = useState<Values>(INITIAL_VALUES);

  function handleChange(unit: Unit, rawValue: string) {
    setValues((previous) => {
      if (rawValue.trim() === '') {
        return { celsius: '', fahrenheit: '', kelvin: '' };
      }

      const numericValue = Number(rawValue);

      if (!Number.isFinite(numericValue)) {
        const onlyActiveValue: Values = {
          celsius: '',
          fahrenheit: '',
          kelvin: '',
        };
        onlyActiveValue[unit] = rawValue;
        return onlyActiveValue;
      }

      const converted = convertFrom(unit, numericValue);
      const next: Values = { ...previous, [unit]: rawValue };

      for (const { key } of UNITS) {
        if (key !== unit) {
          next[key] = formatTemperature(converted[key]);
        }
      }

      return next;
    });
  }

  const isBelowAbsoluteZero = UNITS.some(({ key }) => {
    const numericValue = parseTemperature(values[key]);
    return numericValue !== null && numericValue < ABSOLUTE_ZERO[key];
  });

  return (
    <main style={styles.main}>
      <section style={styles.card} aria-labelledby="converter-title">
        <h1 id="converter-title" style={styles.h1}>
          Temperature Converter
        </h1>
        <p style={styles.intro}>
          Type a temperature in any field. The other two scales update
          automatically.
        </p>

        <div style={styles.grid}>
          {UNITS.map(({ key, label, symbol }) => (
            <div key={key} style={styles.field}>
              <label htmlFor={`temperature-${key}`} style={styles.label}>
                {label}
              </label>
              <div style={styles.inputRow}>
                <input
                  id={`temperature-${key}`}
                  type="text"
                  inputMode="decimal"
                  autoComplete="off"
                  value={values[key]}
                  onChange={(event) => handleChange(key, event.target.value)}
                  style={styles.input}
                  aria-invalid={isBelowAbsoluteZero || undefined}
                />
                <span style={styles.suffix}>{symbol}</span>
              </div>
            </div>
          ))}
        </div>

        {isBelowAbsoluteZero && (
          <p role="alert" style={styles.warning}>
            This temperature is below absolute zero. Enter a physically valid
            value.
          </p>
        )}

        <p style={styles.hint}>
          Absolute zero is 0 K, -273.15 °C, or -459.67 °F.
        </p>
      </section>
    </main>
  );
}
