Replace/create `app/page.tsx` with this single-file page. It uses a Client Component, includes optional local persistence via `localStorage`, and needs no backend.

```tsx
"use client";

import { useEffect, useMemo, useState } from "react";
import type { FormEvent } from "react";

type Book = {
  id: string;
  title: string;
  author: string;
  read: boolean;
};

const STORAGE_KEY = "reading-list-books";

function createId() {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }

  return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function isBook(value: unknown): value is Book {
  if (!value || typeof value !== "object") return false;

  const book = value as Record<string, unknown>;

  return (
    typeof book.id === "string" &&
    typeof book.title === "string" &&
    typeof book.author === "string" &&
    typeof book.read === "boolean"
  );
}

export default function ReadingListPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [hasLoaded, setHasLoaded] = useState(false);

  // Load from localStorage after mount so server/client HTML matches.
  useEffect(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);

      if (stored) {
        const parsed: unknown = JSON.parse(stored);

        if (Array.isArray(parsed)) {
          setBooks(parsed.filter(isBook));
        }
      }
    } catch {
      // Ignore malformed localStorage data.
    } finally {
      setHasLoaded(true);
    }
  }, []);

  // Persist after the initial load.
  useEffect(() => {
    if (!hasLoaded) return;

    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
  }, [books, hasLoaded]);

  const unreadCount = useMemo(
    () => books.filter((book) => !book.read).length,
    [books],
  );

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const trimmedTitle = title.trim();
    const trimmedAuthor = author.trim();

    if (!trimmedTitle) return;

    setBooks((current) => [
      {
        id: createId(),
        title: trimmedTitle,
        author: trimmedAuthor,
        read: false,
      },
      ...current,
    ]);

    setTitle("");
    setAuthor("");
  }

  function toggleRead(id: string) {
    setBooks((current) =>
      current.map((book) =>
        book.id === id ? { ...book, read: !book.read } : book,
      ),
    );
  }

  function removeBook(id: string) {
    setBooks((current) => current.filter((book) => book.id !== id));
  }

  return (
    <main className="page">
      <section className="card">
        <header className="header">
          <div>
            <h1>Reading List</h1>
            <p className="subtitle" aria-live="polite">
              {unreadCount === 0
                ? "You’re all caught up."
                : `${unreadCount} unread book${unreadCount === 1 ? "" : "s"}.`}
            </p>
          </div>

          <span className="badge">{unreadCount} unread</span>
        </header>

        <form className="form" onSubmit={handleSubmit}>
          <div className="field">
            <label htmlFor="title">Title</label>
            <input
              id="title"
              name="title"
              type="text"
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder="e.g. The Left Hand of Darkness"
              autoComplete="off"
              required
            />
          </div>

          <div className="field">
            <label htmlFor="author">Author (optional)</label>
            <input
              id="author"
              name="author"
              type="text"
              value={author}
              onChange={(event) => setAuthor(event.target.value)}
              placeholder="e.g. Ursula K. Le Guin"
              autoComplete="off"
            />
          </div>

          <button type="submit" className="primary">
            Add book
          </button>
        </form>

        {books.length === 0 ? (
          <p className="empty">No books yet. Add your first one above.</p>
        ) : (
          <ul className="list">
            {books.map((book) => (
              <li key={book.id} className={`item ${book.read ? "read" : ""}`}>
                <label className="checkbox">
                  <input
                    type="checkbox"
                    checked={book.read}
                    onChange={() => toggleRead(book.id)}
                    aria-label={`Mark ${book.title} as ${
                      book.read ? "unread" : "read"
                    }`}
                  />
                </label>

                <div className="details">
                  <span className="book-title">{book.title}</span>
                  {book.author && (
                    <span className="book-author">by {book.author}</span>
                  )}
                </div>

                <button
                  type="button"
                  className="remove"
                  onClick={() => removeBook(book.id)}
                  aria-label={`Remove ${book.title}`}
                >
                  Remove
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <style>{`
        * {
          box-sizing: border-box;
        }

        body {
          margin: 0;
          font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
            "Segoe UI", sans-serif;
          background: #f4f4f5;
          color: #18181b;
        }

        .page {
          min-height: 100vh;
          display: grid;
          place-items: start center;
          padding: 48px 16px;
          background: #f4f4f5;
        }

        .card {
          width: min(720px, 100%);
          background: white;
          border: 1px solid #e4e4e7;
          border-radius: 16px;
          padding: 28px;
          box-shadow: 0 18px 45px rgba(24, 24, 27, 0.08);
        }

        .header {
          display: flex;
          align-items: flex-start;
          justify-content: space-between;
          gap: 16px;
          margin-bottom: 24px;
        }

        h1 {
          margin: 0;
          font-size: 2rem;
          letter-spacing: -0.04em;
        }

        .subtitle {
          margin: 8px 0 0;
          color: #71717a;
        }

        .badge {
          flex: none;
          background: #18181b;
          color: white;
          border-radius: 999px;
          padding: 8px 12px;
          font-size: 0.85rem;
          font-weight: 600;
        }

        .form {
          display: grid;
          grid-template-columns: 1fr 1fr auto;
          gap: 12px;
          align-items: end;
          padding: 16px;
          background: #fafafa;
          border: 1px solid #e4e4e7;
          border-radius: 12px;
          margin-bottom: 20px;
        }

        .field {
          display: grid;
          gap: 6px;
        }

        label {
          font-size: 0.82rem;
          font-weight: 600;
          color: #3f3f46;
        }

        input[type="text"] {
          width: 100%;
          border: 1px solid #d4d4d8;
          border-radius: 8px;
          padding: 10px 12px;
          font: inherit;
          background: white;
        }

        input[type="text"]:focus {
          outline: 2px solid #18181b;
          outline-offset: 1px;
          border-color: transparent;
        }

        button {
          font: inherit;
          cursor: pointer;
        }

        .primary {
          background: #18181b;
          color: white;
          border: 0;
          border-radius: 8px;
          padding: 11px 16px;
          font-weight: 600;
          white-space: nowrap;
        }

        .primary:hover {
          background: #27272a;
        }

        .list {
          list-style: none;
          padding: 0;
          margin: 0;
          display: grid;
          gap: 10px;
        }

        .item {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 14px;
          border: 1px solid #e4e4e7;
          border-radius: 10px;
        }

        .item.read {
          background: #fafafa;
        }

        .checkbox {
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
        }

        .checkbox input {
          width: 20px;
          height: 20px;
          accent-color: #18181b;
          cursor: pointer;
        }

        .details {
          display: grid;
          gap: 4px;
          min-width: 0;
          flex: 1;
        }

        .book-title {
          font-weight: 600;
          overflow-wrap: anywhere;
        }

        .item.read .book-title {
          text-decoration: line-through;
          color: #71717a;
        }

        .book-author {
          font-size: 0.9rem;
          color: #71717a;
        }

        .remove {
          background: transparent;
          border: 1px solid #e4e4e7;
          border-radius: 8px;
          padding: 7px 10px;
          color: #71717a;
        }

        .remove:hover {
          color: #b91c1c;
          border-color: #fecaca;
          background: #fef2f2;
        }

        .empty {
          margin: 0;
          text-align: center;
          padding: 24px;
          color: #71717a;
          border: 1px dashed #d4d4d8;
          border-radius: 10px;
        }

        @media (max-width: 640px) {
          .card {
            padding: 20px;
          }

          .form {
            grid-template-columns: 1fr;
          }

          .header {
            flex-direction: column;
          }
        }
      `}</style>
    </main>
  );
}
```

Run `npm run dev` and open the app. The unread count updates automatically, and the list is saved in `localStorage`.

