import { useEffect, useState } from "react";

const SWATCHES = [
  "#0f172a", "#334155", "#64748b", "#cbd5e1",
  "#7f1d1d", "#dc2626", "#f97316", "#facc15",
  "#14532d", "#16a34a", "#2dd4bf", "#0ea5e9",
  "#1e3a8a", "#6366f1", "#a855f7", "#ec4899",
];

export default function SwatchGrid() {
  const [copied, setCopied] = useState<string | null>(null);

  useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(null), 1500);
    return () => window.clearTimeout(timer);
  }, [copied]);

  async function copy(hex: string) {
    try {
      await navigator.clipboard.writeText(hex);
      setCopied(hex);
    } catch {
      setCopied(null);
    }
  }

  return (
    <section className="mx-auto mt-10 max-w-sm p-4">
      <h1 className="mb-4 text-xl font-semibold">Pick a color</h1>
      <div className="grid grid-cols-4 gap-3">
        {SWATCHES.map((hex) => (
          <button
            key={hex}
            onClick={() => copy(hex)}
            aria-label={`Copy ${hex}`}
            className="aspect-square rounded-lg shadow ring-offset-2 hover:ring-2 hover:ring-slate-400"
            style={{ backgroundColor: hex }}
          />
        ))}
      </div>
      <p aria-live="polite" className="mt-4 h-6 text-sm text-slate-600">
        {copied ? `Copied ${copied}` : ""}
      </p>
    </section>
  );
}
