```tsx
// Stopwatch.tsx
import { useCallback, useEffect, useRef, useState } from "react";

type Lap = { number: number; time: number };

function formatTime(ms: number): string {
  const totalCs = Math.floor(ms / 10);
  const cs = totalCs % 100;
  const totalSec = Math.floor(totalCs / 100);
  const sec = totalSec % 60;
  const min = Math.floor(totalSec / 60);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(min)}:${pad(sec)}.${pad(cs)}`;
}

export default function Stopwatch() {
  const [now, setNow] = useState(0); // displayed elapsed time (ms)
  const [running, setRunning] = useState(false);
  const [laps, setLaps] = useState<Lap[]>([]); // newest first

  const accumulatedRef = useRef(0); // ms accumulated before current run segment
  const startRef = useRef<number | null>(null); // performance.now() at start
  const rafRef = useRef<number | null>(null);

  const getElapsed = useCallback(() => {
    const base = accumulatedRef.current;
    return startRef.current === null
      ? base
      : base + (performance.now() - startRef.current);
  }, []);

  const tick = useCallback(() => {
    setNow(getElapsed());
    rafRef.current = requestAnimationFrame(tick);
  }, [getElapsed]);

  const start = useCallback(() => {
    if (startRef.current !== null) return; // already running
    startRef.current = performance.now();
    setRunning(true);
    rafRef.current = requestAnimationFrame(tick);
  }, [tick]);

  const stop = useCallback(() => {
    if (startRef.current === null) return;
    accumulatedRef.current = getElapsed();
    startRef.current = null;
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    setNow(accumulatedRef.current);
    setRunning(false);
  }, [getElapsed]);

  const reset = useCallback(() => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    accumulatedRef.current = 0;
    startRef.current = null;
    setNow(0);
    setRunning(false);
    setLaps([]);
  }, []);

  const recordLap = useCallback(() => {
    if (startRef.current === null) return;
    const time = getElapsed();
    setLaps((prev) => [{ number: prev.length + 1, time }, ...prev]);
  }, [getElapsed]);

  // Cancel the animation frame on unmount
  useEffect(() => {
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const canReset = running || now > 0 || laps.length > 0;

  return (
    <div className="flex min-h-screen items-center justify-center bg-slate-950 p-4">
      <div className="w-full max-w-sm rounded-2xl border border-white/10 bg-slate-900 p-6 shadow-2xl">
        {/* Time display */}
        <div className="select-none text-center font-mono text-6xl leading-none tabular-nums text-white">
          {formatTime(now)}
        </div>
        <p className="mt-2 text-center text-xs uppercase tracking-[0.2em] text-slate-500">
          {running ? "Running" : now > 0 ? "Paused" : "Ready"}
        </p>

        {/* Controls */}
        <div className="mt-6 grid grid-cols-3 gap-3">
          <button
            type="button"
            onClick={running ? stop : start}
            className={`rounded-xl px-4 py-3 text-sm font-semibold text-white shadow-sm transition active:scale-95 ${
              running
                ? "bg-rose-500 hover:bg-rose-400"
                : "bg-emerald-500 hover:bg-emerald-400"
            }`}
          >
            {running ? "Stop" : "Start"}
          </button>

          <button
            type="button"
            onClick={recordLap}
            disabled={!running}
            className="rounded-xl bg-sky-500 px-4 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-sky-400 active:scale-95 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Lap
          </button>

          <button
            type="button"
            onClick={reset}
            disabled={!canReset}
            className="rounded-xl bg-slate-700 px-4 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-600 active:scale-95 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Reset
          </button>
        </div>

        {/* Laps (newest first) */}
        <div className="mt-6">
          <div className="flex items-center justify-between px-1 pb-2 text-xs uppercase tracking-wider text-slate-500">
            <span>Laps</span>
            <span>{laps.length}</span>
          </div>
          <ul className="max-h-64 divide-y divide-white/5 overflow-y-auto rounded-xl bg-slate-800/60 ring-1 ring-white/5">
            {laps.length === 0 ? (
              <li className="px-4 py-6 text-center text-sm text-slate-500">
                No laps recorded
              </li>
            ) : (
              laps.map((lap) => (
                <li
                  key={lap.number}
                  className="flex items-center justify-between px-4 py-2.5 text-sm"
                >
                  <span className="font-medium text-slate-400">
                    Lap {String(lap.number).padStart(2, "0")}
                  </span>
                  <span className="font-mono tabular-nums text-slate-100">
                    {formatTime(lap.time)}
                  </span>
                </li>
              ))
            )}
          </ul>
        </div>
      </div>
    </div>
  );
}
```

Notes on behavior:

- **Timing** uses `performance.now()` plus a `requestAnimationFrame` loop, so the display stays accurate and survives tab throttling when resumed.
- **Start/Stop** toggles; **Reset** stops and clears both time and laps; **Lap** is only enabled while running and records the absolute elapsed time, with the newest lap rendered at the top.
- **Formatting** is `mm:ss.cc` (hundredths), computed with integer math to avoid floating-point artifacts.
- Refs (rather than state) hold the accumulated time and start timestamp, so handlers never read stale values.

