```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Memory</title>
<style>
  body { font-family: system-ui, sans-serif; background: #f4efe6; display: grid; place-items: center; min-height: 100vh; margin: 0; }
  #grid { display: grid; grid-template-columns: repeat(4, 72px); gap: 10px; }
  .card { width: 72px; height: 72px; border: 0; border-radius: 10px; font-size: 32px; cursor: pointer; background: #3d405b; color: transparent; }
  .card.open, .card.done { background: #fff; color: inherit; cursor: default; }
  .card.done { outline: 3px solid #81b29a; }
</style>
</head>
<body>
<main>
  <h1>Memory</h1>
  <p>Moves: <span id="moves">0</span> <span id="message"></span></p>
  <div id="grid"></div>
  <button id="again">Shuffle again</button>
</main>
<script>
const FACES = ["🍎", "🚲", "🎈", "🌵", "🐢", "⚓", "🎲", "🔔"];
const grid = document.getElementById("grid");
let open = [], moves = 0, matched = 0, busy = false;

function shuffle(items) {
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function deal() {
  grid.textContent = "";
  open = []; moves = 0; matched = 0; busy = false;
  document.getElementById("moves").textContent = "0";
  document.getElementById("message").textContent = "";
  for (const face of shuffle([...FACES, ...FACES])) {
    const card = document.createElement("button");
    card.className = "card";
    card.textContent = face;
    card.addEventListener("click", () => flip(card));
    grid.appendChild(card);
  }
}

function flip(card) {
  if (busy || card.classList.contains("open") || card.classList.contains("done")) return;
  card.classList.add("open");
  open.push(card);
  if (open.length < 2) return;
  document.getElementById("moves").textContent = String(++moves);
  const [a, b] = open;
  open = [];
  if (a.textContent === b.textContent) {
    a.classList.add("done"); b.classList.add("done");
    if (++matched === FACES.length) {
      document.getElementById("message").textContent = `- all pairs found in ${moves} moves!`;
    }
  } else {
    busy = true;
    setTimeout(() => { a.classList.remove("open"); b.classList.remove("open"); busy = false; }, 800);
  }
}

document.getElementById("again").addEventListener("click", deal);
deal();
</script>
</body>
</html>
```
